style.css@1791234664.784308.text:
body { font-family: Georgia, serif; margin: 0; color: #3b2a1a; background: #fff8ef; }
header { display: flex; justify-content: space-between; padding: 16px 24px; background: #f3dfc1; }
nav a { margin-left: 16px; }
main { padding: 24px; }
table { width: 100%; border-collapse: collapse; }
td { padding: 10px 4px; border-bottom: 1px solid #ead7bd; }
@media (max-width: 600px) { main { padding: 16px; } tr, td { display: block; } td + td { font-size: 14px; border: 0; padding-top: 0; } }
